import{_ as m,C as e,o as p,c as n,j as t,a as s,E as i,ag as c}from"./chunks/framework.DUTPmUpA.js";const d="/_assets/JauntyQuickArcticwolf.CbggVKfm.mp4",g="/_assets/i3ayn-10871a9310.CgWmW5qY.png",_="/_assets/i3aCO-4887dee9a8.0m2lyu1J.png",h="/_assets/i3aCw-5df098fb34.-Tr3704Q.png",b="/_assets/i3aF1-ac40c1028e.gfU9J1dt.png",u="/_assets/i3aHy-2c37903006.Du_sgoMn.png",f="/_assets/i3aIq-aa87bc8d72.Csi6xDfn.png",v="/_assets/i3byq-f3640f6f4b.Bt8hbL4a.png",V="/_assets/i3aJa-775179ec38.-3EUMdXV.jpg",T="/_assets/i3aKg-33590b10c1.CMHA20Xb.jpg",C="/_assets/i3bEp-1176075e01.ByeCapIw.png",k="/_assets/i3cT8-8962d8e943.BJGjTUUy.png",q="/_assets/i3cQg-76e8c16b46.WymCeiUb.png",x="/_assets/i3d02-b647383364.Dv6tpssR.png",A="/_assets/i3d8I-b8d0e0b25d.Be4tX22H.png",P="/_assets/Bbu4VtP.BFzrzLoz.jpg",D="/_assets/Jbw6kyq.CcVhBBrQ.jpg",y="/_assets/i3gPC-eb6efe93f2.CwQUsqEz.jpg",w="/_assets/Q7VH7Nq.C8d99IoM.png",M="/_assets/MQmf1IM.Ci1mmfyM.jpg",S="/_assets/NgZbK7n.DhnnwW13.png",G="/_assets/oRNgV71.Dl5rvaaS.png",B="/_assets/o22c9Iy.QHYPJ7gY.jpg",L="/_assets/5BvFhPg.k3EDjvLW.png",F="/_assets/GPPJld3.BcJeC6Ox.png",I="/_assets/i3xPr-4ac46797fe.64LqZRCV.png",N="/_assets/i3yr7-447456fe3a.BVfjj_yr.png",o="/_assets/i3yyc-2bde52de31.Dt_7qPLj.png",j="/_assets/i3yxi-2cbd4d5b16.lk1xSpOZ.png",E="/_assets/i3yki-3624cba10a.CBNxH7EN.png",H="/_assets/i3ymK-0c24d9b35c.BW8aKoKV.png",Y=JSON.parse('{"title":"Конвертация MDL в VMDL","description":"","frontmatter":{"title":"Конвертация MDL в VMDL","author":"Noya","steamId":"76561198046984233","date":"28.05.2015"},"headers":[],"relativePath":"assets/models/mdl-to-vmdl-conversion.md","filePath":"assets/models/mdl-to-vmdl-conversion.md"}'),J={name:"assets/models/mdl-to-vmdl-conversion.md"};function K(O,a,Q,U,W,z){const r=e("StaticVideo"),l=e("Gfycat");return p(),n("div",null,[a[0]||(a[0]=t("h1",{id:"конвертация-mdl-в-vmdl",tabindex:"-1"},[s("Конвертация MDL в VMDL "),t("a",{class:"header-anchor",href:"#конвертация-mdl-в-vmdl","aria-label":'Permalink to "Конвертация MDL в VMDL"'},"​")],-1)),a[1]||(a[1]=t("p",null,[s("В этом руководстве будет описан процесс создания файла "),t("strong",null,[t("code",null,".vmdl")]),s(" (модель Source 2) из файла "),t("strong",null,[t("code",null,".mdl")]),s(" и других файлов, связанных с моделью, из Source 1. В качестве примера будет использоваться курьер Wyvern Hatchling, но тот же процесс применим к героям, зданиям и любой модели Valve Dota.")],-1)),i(r,{path:d}),a[2]||(a[2]=c('<h2 id="необходимые-инструменты" tabindex="-1">Необходимые инструменты <a class="header-anchor" href="#необходимые-инструменты" aria-label="Permalink to &quot;Необходимые инструменты&quot;">​</a></h2><ul><li><a href="https://developer.valvesoftware.com/wiki/GCFScape" target="_blank" rel="noreferrer">GCFScape</a> или <a href="https://s2v.app/" target="_blank" rel="noreferrer">Source 2 Viewer</a></li><li><a href="https://steamcommunity.com/groups/CrowbarTool/discussions/0/617328415069203029/" target="_blank" rel="noreferrer">Crowbar</a></li><li><a href="https://developer.valvesoftware.com/wiki/VTFEdit" target="_blank" rel="noreferrer">VTFEdit</a></li><li>Инструменты мастерской (редактор материалов и моделей)</li></ul><h2 id="шаг-1-получите-фаилы-model-и-material-из-vpk-основнои-игры-pak01-dir-vpk-с-помощью-gcfscape" tabindex="-1">Шаг 1. Получите файлы <strong>model</strong> и <strong>material</strong> из VPK основной игры (<code>pak01_dir.vpk</code>) с помощью GCFScape. <a class="header-anchor" href="#шаг-1-получите-фаилы-model-и-material-из-vpk-основнои-игры-pak01-dir-vpk-с-помощью-gcfscape" aria-label="Permalink to &quot;Шаг 1. Получите файлы **model** и **material** из VPK основной игры (`pak01_dir.vpk`) с помощью GCFScape.&quot;">​</a></h2><p>Требуются следующие типы файлов:</p><ul><li><code>.mdl</code></li><li><code>.vvd</code></li><li><code>.dx90.vtx</code></li><li><code>.vtf</code></li></ul><p>Файлы моделей будут находиться в подпапке папки <em>/models/</em>: <img src="'+g+'" alt="img"></p><p>Щелкните правой кнопкой мыши и извлеките файл в папку по вашему выбору.</p><p><img src="'+_+'" alt="img"></p><p>Файлы цветных материалов расположены в папке <em>materials/models/</em>. В этом примере у этого курьера есть 3 связанных файла цвета, по одному для каждого скина, поэтому мы получим</p><p><img src="'+h+'" alt="img"></p><p>Наконец, у нас должно быть следующее: <img src="'+b+'" alt="img"></p><h2 id="шаг-2-используите-crowbar-для-декомпиляции-фаилов-модели-в-сетки-smd" tabindex="-1">Шаг 2. Используйте Crowbar для декомпиляции файлов модели в сетки (<code>.smd</code>) <a class="header-anchor" href="#шаг-2-используите-crowbar-для-декомпиляции-фаилов-модели-в-сетки-smd" aria-label="Permalink to &quot;Шаг 2. Используйте Crowbar для декомпиляции файлов модели в сетки (`.smd`)&quot;">​</a></h2><p><img src="'+u+'" alt="img"></p><p><img src="'+f+'" alt="img"></p><p>Результат в выходной папке:</p><p><img src="'+v+'" alt="img"></p><h2 id="шаг-3-используите-vtfedit-для-создания-цветных-tga-из-фаилов-vtf-полученных-на-шаге-1" tabindex="-1">Шаг 3. Используйте VTFEdit для создания цветных TGA из файлов VTF, полученных на шаге 1. <a class="header-anchor" href="#шаг-3-используите-vtfedit-для-создания-цветных-tga-из-фаилов-vtf-полученных-на-шаге-1" aria-label="Permalink to &quot;Шаг 3. Используйте VTFEdit для создания цветных TGA из файлов VTF, полученных на шаге 1.&quot;">​</a></h2><p><img src="'+V+'" alt="img"></p><p><img src="'+T+'" alt="img"></p><p>Делаем Файл-&gt;Экспорт.</p><p>Результат (<a href="https://www.irfanview.com/" target="_blank" rel="noreferrer">IrfanView</a> — это программа просмотра изображений старой школы, которая прекрасно открывает TGA):</p><p><img src="'+C+'" alt="img"></p><h2 id="шаг-4-переместите-сгенерированные-фаилы-в-папку-дополнении-content" tabindex="-1">Шаг 4. Переместите сгенерированные файлы в папку дополнений <strong>/content/</strong>. <a class="header-anchor" href="#шаг-4-переместите-сгенерированные-фаилы-в-папку-дополнении-content" aria-label="Permalink to &quot;Шаг 4. Переместите сгенерированные файлы в папку дополнений **/content/**.&quot;">​</a></h2><ul><li>Переместите декомпилированные файлы, созданные на шаге 2, в <strong>/content/models/</strong>.</li></ul><p><img src="'+k+'" alt="img"></p><ul><li>Переместите файлы TGA, созданные на шаге 3, в <strong>/content/materials/</strong>.</li></ul><p><img src="'+q+'" alt="img"></p><p>Создайте новые папки для каждого или просто перетащите файлы в соответствующие каталоги. Обязательно используйте папку содержимого (а не /game/). <br>Расположение эталонной сетки в /content/models/ определит место, где будет сохранен файл .vmdl.</p><h2 id="шаг-5-создаите-фаил-vmat-из-фаилов-tga" tabindex="-1">Шаг 5. Создайте файл <code>.vmat</code> из файлов TGA. <a class="header-anchor" href="#шаг-5-создаите-фаил-vmat-из-фаилов-tga" aria-label="Permalink to &quot;Шаг 5. Создайте файл `.vmat` из файлов TGA.&quot;">​</a></h2><ul><li>Откройте редактор материалов.</li><li>Файл -&gt; Новый материал</li><li>Пока ничего не делая, <strong>сохраните</strong> пустой материал с именем TGA, для которого вы хотите создать <code>.vmat</code>. <img src="'+x+'" alt="img"></li><li>Просмотрите и найдите TGA для использования <img src="'+A+'" alt="img">.</li><li>По умолчанию файл должен быть виден с расширением <code>_color.</code> <img src="'+P+'" alt="img">.</li><li>Сохраните окончательный материал. <img src="'+D+'" alt="img"></li></ul><h2 id="шаг-6-создаите-новыи-vmdl-из-фаила-сетки-smd" tabindex="-1">Шаг 6. Создайте новый VMDL из файла сетки (<code>.smd</code>) <a class="header-anchor" href="#шаг-6-создаите-новыи-vmdl-из-фаила-сетки-smd" aria-label="Permalink to &quot;Шаг 6. Создайте новый VMDL из файла сетки (`.smd`)&quot;">​</a></h2><ul><li>Откройте редактор моделей</li><li>Новый VMDL из файла сетки (Ctrl+M) <img src="'+y+'" alt="img"></li><li>Выберите эталонный файл <code>.smd</code>, созданный на шаге 2. <img src="'+w+'" alt="img">.</li><li>Если все прошло хорошо, вы должны увидеть красную сетку ошибки: <img src="'+M+'" alt="img">.</li></ul><h2 id="шаг-7-добавьте-переназначение-материала-для-отсутствующих-текстур-используя-фаил-vmat-из-шага-5" tabindex="-1">Шаг 7. Добавьте переназначение материала для отсутствующих текстур, используя файл .vmat из шага 5. <a class="header-anchor" href="#шаг-7-добавьте-переназначение-материала-для-отсутствующих-текстур-используя-фаил-vmat-из-шага-5" aria-label="Permalink to &quot;Шаг 7. Добавьте переназначение материала для отсутствующих текстур, используя файл .vmat из шага 5.&quot;">​</a></h2><ul><li><p>В меню Модель -&gt; Добавить переназначение материала <img src="'+S+'" alt="img">.</p></li><li><p>Выберите список переназначения материалов и сверните свойства в редакторе свойств <img src="'+G+'" alt="img">.</p></li><li><p>Поиск материала, выберите его из раскрывающегося списка. Это недостающие материалы, которые необходимо переназначить на созданный ранее .vmat.</p></li><li><p>Ctrl+S, чтобы сохранить модель, теперь модель объединяется с текстурой и принимает форму: <img src="'+B+'" alt="img"></p></li><li><p>ЕСЛИ на модели отображается сообщение <strong>Ошибка</strong>, что-то пошло не так. Обязательно удалите автоматически скомпилированные модели и одноименные материалы из папок /game/, которые теперь повреждены. Убедитесь, что все использует правильные имена и каталоги, иногда кажется, что редактор модели/материала не работает и делает что-то Volvo.</p></li></ul><h2 id="шаг-8-добавьте-анимации-в-папку-anims-и-создаите-для-них-деиствия" tabindex="-1">Шаг 8. Добавьте анимации в папку <code>_anims</code> и создайте для них действия. <a class="header-anchor" href="#шаг-8-добавьте-анимации-в-папку-anims-и-создаите-для-них-деиствия" aria-label="Permalink to &quot;Шаг 8. Добавьте анимации в папку `_anims` и создайте для них действия.&quot;">​</a></h2><p><img src="'+L+'" alt="img"></p><p>Выберите их все.</p><p><img src="'+F+'" alt="img"> Анимации теперь будут просматриваться при нажатии на них, модель будет двигаться, но для того, чтобы игра могла использовать анимацию, ей необходимо действие (строки ACT_DOTA_name).</p><p>В окне «Последовательности» («Инструменты выполнения» -&gt; «Просмотр последовательностей», если оно не отображается) убедитесь, что выбран вариант <strong>Активность</strong>. Он покажет пустой список в скобках []</p><p><img src="'+I+'" alt="img"></p><p>Теперь выберите каждую анимацию, для которой вы хотите создать действие.</p><p><img src="'+N+'" alt="img"></p><p>В редакторе свойств есть элемент «Действия», который по умолчанию будет содержать 0 элементов. Нажмите на ****+**, чтобы добавить его. <img src="'+o+'" alt="img"></p><p>Добавьте к нему Имя, попробуйте использовать ACT_DOTA_name, которое лучше соответствует описанию действия.</p><p><img src="'+j+'" alt="img"></p><p>Наконец, у нас есть полезные анимации:</p><p><img src="'+o+'" alt="img"></p><p>::: информация Это также полезно для доступа к некоторым действиям ACT_DOTA_ACTIVITY+<strong>string</strong>, которые используются в некоторых анимациях насмешек и альтернативных анимаций, которые в настоящее время нельзя использовать для способностей и других целей (поскольку они просто игнорируют часть <strong>+string</strong>). Зная это, можно назначить некоторую неиспользуемую строку активности, например «ACT_DOTA_MINI_TAUNT», и принудительно использовать ее через <code>OverrideAnimation</code> KV. :::</p><h2 id="step-9-add-the-hitboxes" tabindex="-1">Step 9. Add the Hitboxes <a class="header-anchor" href="#step-9-add-the-hitboxes" aria-label="Permalink to &quot;Step 9. Add the Hitboxes&quot;">​</a></h2><p>Go to Model-&gt;Hitboxes-&gt;Auto Populate and accept the list of all bones.</p><p><img src="'+E+'" alt="img"></p><p>Если вы включите «Отображение-&gt; Хитбоксы и имена хитбоксов», вы должны увидеть что-то вроде этого:</p><p><img src="'+H+'" alt="img"></p><hr><p>Конечным результатом является готовая модель со всеми ее анимациями (надеюсь):</p>',55)),i(l,{id:"FirmEthicalHylaeosaurus"})])}const $=m(J,[["render",K]]);export{Y as __pageData,$ as default};
